// @ts-nocheck
import Fastify, { FastifyReply, FastifyRequest } from 'fastify';
import cors from '@fastify/cors';
import helmet from '@fastify/helmet';
import rateLimit from '@fastify/rate-limit';
import argon2 from 'argon2';
import { Pool } from 'pg';
import crypto from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import dotenv from 'dotenv';
import {askGroqNutrition} from './groq.js';
import {askOpenAIVision} from './vision.js';

dotenv.config();
const app = Fastify({ logger: true });
const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const PORT = Number(process.env.PORT || 3000);
const SESSION_DAYS = Number(process.env.SESSION_DAYS || 14);
const FRONTEND_URL = process.env.FRONTEND_URL || '*';
const FRONTEND_ORIGINS = new Set(FRONTEND_URL==='*' ? [] : FRONTEND_URL.split(',').map(x=>x.trim()).filter(Boolean));
// The repository's Pages origin is a known public deployment target; extra origins stay configurable.
FRONTEND_ORIGINS.add('https://multigymsistema-debug.github.io');
const BIO_KEY = Buffer.from(process.env.BIOMETRIC_ENCRYPTION_KEY || '', 'hex');
if (BIO_KEY.length !== 32) throw new Error('BIOMETRIC_ENCRYPTION_KEY must be a 32-byte hex key');

type User = { id:string; gym_id:string; name:string; email:string; role:string; status:string; gym_name:string; };
type Req = FastifyRequest & { user?: User };

const q = async (text:string, params:any[]=[]):Promise<any[]> => (await pool.query(text, params)).rows;
const one = async (text:string, params:any[]=[]):Promise<any|null> => (await pool.query(text, params)).rows[0] || null;
const hashToken = (token:string) => crypto.createHash('sha256').update(token).digest('hex');
const newToken = () => crypto.randomBytes(48).toString('base64url');
const encrypt = (value:string) => { const iv=crypto.randomBytes(12); const c=crypto.createCipheriv('aes-256-gcm',BIO_KEY,iv); const enc=Buffer.concat([c.update(value,'utf8'),c.final()]); return `${iv.toString('base64url')}.${c.getAuthTag().toString('base64url')}.${enc.toString('base64url')}`; };
const decrypt = (value:string) => { const [ivS,tagS,dataS]=value.split('.'); const d=crypto.createDecipheriv('aes-256-gcm',BIO_KEY,Buffer.from(ivS,'base64url')); d.setAuthTag(Buffer.from(tagS,'base64url')); return Buffer.concat([d.update(Buffer.from(dataS,'base64url')),d.final()]).toString('utf8'); };
const money = (n:any) => Number(Number(n||0).toFixed(2));
const slugify = (s:string) => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,90);
const requireAuth = async (req:Req, reply:FastifyReply) => {
  const header = req.headers.authorization || '';
  if (!header.startsWith('Bearer ')) return reply.code(401).send({error:'Não autenticado'});
  const token=header.slice(7); const row=await one(`SELECT u.id,u.gym_id,u.name,u.email,u.role,u.status,g.name gym_name FROM sessions s JOIN users u ON u.id=s.user_id JOIN gyms g ON g.id=s.gym_id WHERE s.token_hash=$1 AND s.revoked_at IS NULL AND s.expires_at>now() AND u.status='active'`,[hashToken(token)]);
  if(!row) return reply.code(401).send({error:'Sessão expirada'}); req.user=row;
};
const audit = async (u:User, action:string, entity:string, entityId:string|null, metadata:any={}) => { await q(`INSERT INTO audit_logs(gym_id,user_id,action,entity,entity_id,metadata) VALUES($1,$2,$3,$4,$5,$6)`,[u.gym_id,u.id,action,entity,entityId,JSON.stringify(metadata)]); };
const body = (req:FastifyRequest) => (req.body || {}) as any;

await app.register(cors,{origin: FRONTEND_URL==='*' ? true : (origin,cb)=>cb(null,!origin||FRONTEND_ORIGINS.has(origin)), credentials:false});
await app.register(helmet,{contentSecurityPolicy:false});
await app.register(rateLimit,{max:120,timeWindow:'1 minute'});

app.get('/health',async()=>({ok:true,service:'multigym-api',version:'2.0.0'}));

app.post('/api/auth/register',async(req,reply)=>{
  const b=body(req); if(!b.gymName||!b.name||!b.email||!b.password) return reply.code(400).send({error:'Preencha academia, nome, e-mail e senha'});
  if(String(b.password).length<8) return reply.code(400).send({error:'A senha deve ter pelo menos 8 caracteres'});
  const client=await pool.connect();
  try { await client.query('BEGIN'); const slugBase=slugify(b.gymName)||'academia'; let slug=slugBase; let i=1; while((await client.query('SELECT 1 FROM gyms WHERE slug=$1',[slug])).rowCount) slug=`${slugBase}-${i++}`;
    const gym=(await client.query(`INSERT INTO gyms(name,slug,email,phone) VALUES($1,$2,$3,$4) RETURNING *`,[b.gymName,slug,b.email,b.phone||null])).rows[0];
    const passwordHash=await argon2.hash(b.password); const user=(await client.query(`INSERT INTO users(gym_id,name,email,password_hash,role) VALUES($1,$2,$3,$4,'admin') RETURNING id,name,email,role`,[gym.id,b.name,b.email.toLowerCase(),passwordHash])).rows[0];
    await client.query(`INSERT INTO plans(gym_id,name,price,duration_days,description) VALUES ($1,'Mensal',100,30,'Plano mensal padrão'),($1,'Trimestral',270,90,'Plano trimestral'),($1,'Semestral',500,180,'Plano semestral') ON CONFLICT(gym_id,name) DO NOTHING`,[gym.id]);
    await client.query(`INSERT INTO exercises(gym_id,name,muscle_group,equipment,difficulty) SELECT $1,v.name,v.muscle,v.equip,v.diff FROM (VALUES ('Supino reto','Peito','Barra','intermediate'),('Supino inclinado','Peito','Halteres','intermediate'),('Crucifixo','Peito','Máquina','beginner'),('Puxada frontal','Costas','Polia','beginner'),('Remada baixa','Costas','Polia','beginner'),('Agachamento livre','Pernas','Barra','advanced'),('Leg press','Pernas','Máquina','beginner'),('Cadeira extensora','Pernas','Máquina','beginner'),('Mesa flexora','Pernas','Máquina','beginner'),('Elevação lateral','Ombros','Halteres','beginner'),('Desenvolvimento','Ombros','Halteres','intermediate'),('Rosca direta','Bíceps','Barra','beginner'),('Tríceps pulley','Tríceps','Polia','beginner'),('Abdominal','Abdômen','Peso corporal','beginner')) v(name,muscle,equip,diff) ON CONFLICT(gym_id,name) DO NOTHING`,[gym.id]);
    await client.query('COMMIT'); const token=newToken(); await q(`INSERT INTO sessions(user_id,gym_id,token_hash,expires_at) VALUES($1,$2,$3,now()+($4||' days')::interval)`,[user.id,gym.id,hashToken(token),SESSION_DAYS]);
    return reply.send({token,user:{...user,gym_id:gym.id,gym_name:gym.name}});
  } catch(e){ await client.query('ROLLBACK'); app.log.error(e); return reply.code(400).send({error:'Não foi possível criar a academia. Verifique os dados.'}); } finally{client.release();}
});

app.post('/api/auth/login',async(req,reply)=>{ const b=body(req); const u=await one(`SELECT u.*,g.name gym_name FROM users u JOIN gyms g ON g.id=u.gym_id WHERE lower(u.email)=lower($1) AND u.status='active'`,[b.email||'']); if(!u||!(await argon2.verify(u.password_hash,b.password||''))) return reply.code(401).send({error:'E-mail ou senha inválidos'}); const token=newToken(); await q(`INSERT INTO sessions(user_id,gym_id,token_hash,expires_at) VALUES($1,$2,$3,now()+($4||' days')::interval)`,[u.id,u.gym_id,hashToken(token),SESSION_DAYS]); await q(`UPDATE users SET last_login_at=now() WHERE id=$1`,[u.id]); return {token,user:{id:u.id,gym_id:u.gym_id,name:u.name,email:u.email,role:u.role,gym_name:u.gym_name}}; });
app.post('/api/auth/logout',{preHandler:requireAuth},async(req:Req,reply)=>{ const t=(req.headers.authorization||'').slice(7); await q(`UPDATE sessions SET revoked_at=now() WHERE token_hash=$1`,[hashToken(t)]); return {ok:true}; });
app.get('/api/me',{preHandler:requireAuth},async(req:Req)=>({user:req.user}));

app.get('/api/dashboard',{preHandler:requireAuth},async(req:Req)=>{ const g=req.user!.gym_id;
  const [kpi,finance,presence,renewals,recentStudents,workouts,appointments,lowStock] = await Promise.all([
    one(`SELECT (SELECT count(*) FROM students WHERE gym_id=$1 AND status='active') active_students,(SELECT count(*) FROM enrollments WHERE gym_id=$1 AND ends_on BETWEEN CURRENT_DATE AND CURRENT_DATE+7 AND status IN('active','expiring')) expiring,(SELECT count(*) FROM enrollments WHERE gym_id=$1 AND ends_on<CURRENT_DATE AND status<>'cancelled') expired,(SELECT COALESCE(sum(amount),0) FROM payments WHERE gym_id=$1 AND status='paid' AND paid_at>=date_trunc('month',now())) revenue`,[g]),
    one(`SELECT COALESCE(sum(CASE WHEN status='paid' THEN amount ELSE 0 END),0) received,COALESCE(sum(CASE WHEN status='pending' THEN amount ELSE 0 END),0) pending,COALESCE(sum(CASE WHEN status='paid' THEN amount ELSE 0 END),0) revenue FROM payments WHERE gym_id=$1 AND created_at>=date_trunc('month',now())`,[g]),
    one(`SELECT count(DISTINCT student_id) present FROM checkins WHERE gym_id=$1 AND checked_at >= date_trunc('day',now() AT TIME ZONE 'America/Sao_Paulo')`,[g]),
    q(`SELECT e.id,e.ends_on,e.amount,s.id student_id,s.full_name,p.name plan_name FROM enrollments e JOIN students s ON s.id=e.student_id JOIN plans p ON p.id=e.plan_id WHERE e.gym_id=$1 AND e.ends_on>=CURRENT_DATE AND e.ends_on<=CURRENT_DATE+14 AND e.status<>'cancelled' ORDER BY e.ends_on LIMIT 8`,[g]),
    q(`SELECT id,full_name,phone,created_at FROM students WHERE gym_id=$1 ORDER BY created_at DESC LIMIT 6`,[g]),
    q(`SELECT w.id,w.name,s.full_name FROM workouts w JOIN students s ON s.id=w.student_id WHERE w.gym_id=$1 AND w.status='active' ORDER BY w.updated_at DESC LIMIT 6`,[g]),
    q(`SELECT a.*,s.full_name student_name FROM appointments a LEFT JOIN students s ON s.id=a.student_id WHERE a.gym_id=$1 AND a.starts_at>=CURRENT_DATE AND a.starts_at<CURRENT_DATE+1 ORDER BY a.starts_at LIMIT 8`,[g]),
    q(`SELECT id,name,stock,min_stock FROM products WHERE gym_id=$1 AND active=true AND stock<=min_stock ORDER BY stock LIMIT 8`,[g])
  ]); return {kpi,finance,presence,renewals,recentStudents,workouts,appointments,lowStock};
});

const simpleCrud = (name:string, table:string, fields:string[]) => {
 app.get(`/api/${name}`,{preHandler:requireAuth},async(req:Req)=>{ const search=String((req.query as any)?.search||''); const where=fields.includes('name') ? `AND name ILIKE $2` : ''; return q(`SELECT * FROM ${table} WHERE gym_id=$1 ${where} ORDER BY created_at DESC`,where?[req.user!.gym_id,`%${search}%`]:[req.user!.gym_id]); });
 app.post(`/api/${name}`,{preHandler:requireAuth},async(req:Req,reply)=>{ const b=body(req); if(!b.name) return reply.code(400).send({error:'Nome é obrigatório'}); if(table==='plans' && (!Number.isFinite(Number(b.price)) || Number(b.price)<0 || !Number.isInteger(Number(b.duration_days)) || Number(b.duration_days)<=0)) return reply.code(400).send({error:'Informe um preço válido e a duração do plano em dias.'}); const cols=['gym_id',...fields], vals=[req.user!.gym_id,...fields.map(f=>b[f]??null)], ph=cols.map((_,i)=>`$${i+1}`).join(','); try { const row=await one(`INSERT INTO ${table}(${cols.join(',')}) VALUES(${ph}) RETURNING *`,vals); await audit(req.user!,`create`,table,row.id,b); return reply.code(201).send(row); } catch(e:any){app.log.error(e);return reply.code(400).send({error:e?.code==='23505'?'Já existe um registro com esse nome.':'Não foi possível salvar o registro'});} });
 app.delete(`/api/${name}/:id`,{preHandler:requireAuth},async(req:Req,reply)=>{ try{const row=await one(`DELETE FROM ${table} WHERE id=$1 AND gym_id=$2 RETURNING id`,[(req.params as any).id,req.user!.gym_id]); return row?reply.send({ok:true}):reply.code(404).send({error:'Não encontrado'});}catch(e){return reply.code(400).send({error:'Não foi possível remover o registro'});} });
 app.put(`/api/${name}/:id`,{preHandler:requireAuth},async(req:Req,reply)=>{ const b=body(req); const sets=fields.map((f,i)=>`${f}=$${i+1}`).join(','); try { const row=await one(`UPDATE ${table} SET ${sets},updated_at=now() WHERE id=$${fields.length+1} AND gym_id=$${fields.length+2} RETURNING *`,[...fields.map(f=>b[f]??null),(req.params as any).id,req.user!.gym_id]); return row?reply.send(row):reply.code(404).send({error:'Não encontrado'}); } catch(e){return reply.code(400).send({error:'Não foi possível atualizar'});} });
};
// explicit CRUDs keep API predictable
simpleCrud('plans','plans',['name','price','duration_days','description','status']);
simpleCrud('products','products',['sku','name','category','cost','price','stock','min_stock','active']);
simpleCrud('services','services',['name','description','price','duration_minutes','active']);
app.post('/api/import/aroeira',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req);const students=Array.isArray(b.students)?b.students:[];if(!students.length||students.length>1000)return reply.code(400).send({error:'Envie uma lista de alunos válida (1 a 1000).'});const g=req.user!.gym_id;const client=await pool.connect();const planMap=(raw:any)=>{const n=String(raw||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/’/g,"'").trim();if(n.includes('DIAR'))return {name:'Diária',days:1,price:14.99};if(n.includes('15 DIAS'))return {name:'Crédito 15 dias',days:15,price:0};if(n.includes('30 DIAS'))return {name:'Crédito 30 dias',days:30,price:0};if(n.includes('ANUAL'))return {name:'Plano anual',days:365,price:44.5};if(n.includes('1° MÊS')||n.includes('1 MES'))return {name:'Plano primeiro mês',days:30,price:59.9};if(n.includes('SEM PLANO')||!n)return null;return {name:'Plano mensal',days:30,price:69.9};};const result={received:students.length,created:0,updated:0,plans:0,enrollments:0,payments:0,errors:[] as any[]};try{await client.query('BEGIN');for(const item of students){try{const p=planMap(item.plan);let planId=null;if(p){const pr=await client.query(`INSERT INTO plans(gym_id,name,price,duration_days,description) VALUES($1,$2,$3,$4,$5) ON CONFLICT(gym_id,name) DO UPDATE SET price=EXCLUDED.price,updated_at=now() RETURNING id`,[g,p.name,p.price,p.days,`Importado da base Aroeira G Fitness`]);planId=pr.rows[0].id;if(pr.rowCount)result.plans++;}const name=String(item.name||'').trim();if(!name)throw new Error('Nome ausente');const email=String(item.email||'').trim().toLowerCase()||null;const phone=String(item.phone||'').trim()||null;let st=email?(await client.query('SELECT id FROM students WHERE gym_id=$1 AND lower(email)=lower($2) LIMIT 1',[g,email])).rows[0]:null;if(!st&&phone)st=(await client.query('SELECT id FROM students WHERE gym_id=$1 AND phone=$2 LIMIT 1',[g,phone])).rows[0];if(!st)st=(await client.query('SELECT id FROM students WHERE gym_id=$1 AND lower(full_name)=lower($2) LIMIT 1',[g,name])).rows[0];if(st){await client.query('UPDATE students SET full_name=$1,email=COALESCE($2,email),phone=COALESCE($3,phone),updated_at=now() WHERE id=$4 AND gym_id=$5',[name,email,phone,st.id,g]);result.updated++;}else{st=(await client.query('INSERT INTO students(gym_id,full_name,email,phone) VALUES($1,$2,$3,$4) RETURNING id',[g,name,email,phone])).rows[0];result.created++;}if(planId&&item.due){const due=String(item.due).slice(0,10);const amount=Number(item.value||0);const status=/atras|venc/i.test(String(item.payment||''))?'expired':(new Date(due)<new Date()?'expired':'active');const en=await client.query(`INSERT INTO enrollments(gym_id,student_id,plan_id,starts_on,ends_on,amount,status,notes) VALUES($1,$2,$3,($4::date-$5::int),$4,$6,$7,'Importado da base Aroeira G Fitness') RETURNING id`,[g,st.id,planId,due,p.days,amount,status]);if(en.rowCount)result.enrollments++;}for(const h of Array.isArray(item.paymentHistory)?item.paymentHistory:[]){const ref=`legacy:${item.id||name}:${String(h.date||'').slice(0,10)}`;const exists=await client.query('SELECT 1 FROM payments WHERE gym_id=$1 AND reference=$2 LIMIT 1',[g,ref]);if(!exists.rowCount) {const amount=Number(h.value||item.value||0);if(amount>0){await client.query(`INSERT INTO payments(gym_id,student_id,amount,paid_at,method,status,reference,notes) VALUES($1,$2,$3,$4,'other','paid',$5,'Importado da base Aroeira G Fitness')`,[g,st.id,amount,h.date||null,ref]);result.payments++;}}}}catch(e:any){result.errors.push({name:item.name||null,error:'Registro não importado'});}}await client.query('COMMIT');return reply.send(result);}catch(e){await client.query('ROLLBACK');return reply.code(400).send({error:'Não foi possível concluir a importação.'});}finally{client.release();}});
