app.get('/api/enrollments',{preHandler:requireAuth},async(req:Req)=>q(`SELECT e.*,s.full_name student_name,p.name plan_name FROM enrollments e JOIN students s ON s.id=e.student_id JOIN plans p ON p.id=e.plan_id WHERE e.gym_id=$1 ORDER BY e.ends_on DESC`,[req.user!.gym_id]));

