app.get('/api/checkins/today',{preHandler:requireAuth},async(req:Req)=>q(`SELECT c.*,s.full_name,s.photo_url FROM checkins c JOIN students s ON s.id=c.student_id WHERE c.gym_id=$1 AND c.checked_at>=CURRENT_DATE ORDER BY c.checked_at DESC`,[req.user!.gym_id]));
app.post('/api/checkins',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),g=req.user!.gym_id; const student=await one(`SELECT s.*,e.ends_on FROM students s LEFT JOIN LATERAL(SELECT ends_on FROM enrollments WHERE student_id=s.id AND gym_id=$1 AND status<>'cancelled' ORDER BY ends_on DESC LIMIT 1)e ON true WHERE s.id=$2 AND s.gym_id=$1`,[g,b.student_id]); if(!student)return reply.code(404).send({error:'Aluno não encontrado'}); if(student.status!=='active')return reply.code(400).send({error:'Aluno inativo'}); if(student.ends_on && new Date(student.ends_on)<new Date())return reply.code(400).send({error:'Matrícula vencida'}); const existing=await one(`SELECT * FROM checkins WHERE gym_id=$1 AND student_id=$2 AND checked_at>=CURRENT_DATE`,[g,b.student_id]); if(existing)return {already:true,checkin:existing,student}; const c=await one(`INSERT INTO checkins(gym_id,student_id,method,confidence,created_by) VALUES($1,$2,$3,$4,$5) RETURNING *`,[g,b.student_id,b.method||'manual',b.confidence||null,req.user!.id]); return reply.code(201).send({already:false,checkin:c,student});});

app.post('/api/face/enroll',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),g=req.user!.gym_id; if(!b.student_id||!Array.isArray(b.descriptor)||b.descriptor.length<64||!b.consent)return reply.code(400).send({error:'É necessário descriptor facial e consentimento'}); const student=await one(`SELECT id FROM students WHERE id=$1 AND gym_id=$2`,[b.student_id,g]); if(!student)return reply.code(404).send({error:'Aluno não encontrado'}); const enc=encrypt(JSON.stringify(b.descriptor)); await q(`INSERT INTO face_profiles(gym_id,student_id,descriptor_encrypted,consent_at,revoked_at) VALUES($1,$2,$3,now(),NULL) ON CONFLICT(gym_id,student_id) DO UPDATE SET descriptor_encrypted=EXCLUDED.descriptor_encrypted,consent_at=now(),revoked_at=NULL,updated_at=now()`,[g,b.student_id,enc]); return {ok:true};});
app.delete('/api/face/enroll/:studentId',{preHandler:requireAuth},async(req:Req)=>{await q(`UPDATE face_profiles SET revoked_at=now(),updated_at=now() WHERE student_id=$1 AND gym_id=$2`,[(req.params as any).studentId,req.user!.gym_id]); return {ok:true};});
app.post('/api/face/match',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req); if(!Array.isArray(b.descriptor))return reply.code(400).send({error:'Descriptor inválido'}); const rows=await q(`SELECT fp.student_id,fp.descriptor_encrypted,s.full_name,s.status,e.ends_on FROM face_profiles fp JOIN students s ON s.id=fp.student_id LEFT JOIN LATERAL(SELECT ends_on FROM enrollments WHERE student_id=s.id AND gym_id=$1 AND status<>'cancelled' ORDER BY ends_on DESC LIMIT 1)e ON true WHERE fp.gym_id=$1 AND fp.revoked_at IS NULL AND s.status='active'`,[req.user!.gym_id]); let best:any=null; for(const r of rows){try{const d=JSON.parse(decrypt(r.descriptor_encrypted)); if(d.length!==b.descriptor.length)continue; let sum=0; for(let i=0;i<d.length;i++){const diff=Number(d[i])-Number(b.descriptor[i]); sum+=diff*diff;} const dist=Math.sqrt(sum); if(!best||dist<best.distance)best={student_id:r.student_id,full_name:r.full_name,distance:dist,ends_on:r.ends_on};}catch{}} if(!best||best.distance>Number(b.threshold||0.52))return reply.code(404).send({error:'Rosto não reconhecido'}); return {match:best};});

app.get('/api/cash/current',{preHandler:requireAuth},async(req:Req)=>{const r=await one(`SELECT * FROM cash_registers WHERE gym_id=$1 AND status='open' ORDER BY opened_at DESC LIMIT 1`,[req.user!.gym_id]); if(!r)return {register:null,movements:[]}; const movements=await q(`SELECT * FROM cash_movements WHERE register_id=$1 ORDER BY created_at DESC`,[r.id]); return {register:r,movements};});
const addCashMovement=async(gym:string,type:string,amount:number,method:string,description:string,reference:string|null,user:string)=>{const r=await one(`SELECT id FROM cash_registers WHERE gym_id=$1 AND status='open' ORDER BY opened_at DESC LIMIT 1`,[gym]); if(!r)return null; const dir=['withdrawal'].includes(type)?'out':'in'; return one(`INSERT INTO cash_movements(gym_id,register_id,type,direction,amount,method,description,reference_id,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`,[gym,r.id,type,dir,amount,method,description,reference,user]);};
app.post('/api/cash/open',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req); const open=await one(`SELECT id FROM cash_registers WHERE gym_id=$1 AND status='open'`,[req.user!.gym_id]); if(open)return reply.code(400).send({error:'Já existe um caixa aberto'}); const r=await one(`INSERT INTO cash_registers(gym_id,opened_by,opening_amount) VALUES($1,$2,$3) RETURNING *`,[req.user!.gym_id,req.user!.id,Number(b.opening_amount||0)]); if(Number(b.opening_amount)>0)await addCashMovement(req.user!.gym_id,'supply',Number(b.opening_amount),'cash','Fundo inicial',null,req.user!.id); return reply.code(201).send(r);});
app.post('/api/cash/movement',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req); const r=await one(`SELECT id FROM cash_registers WHERE gym_id=$1 AND status='open'`,[req.user!.gym_id]); if(!r)return reply.code(400).send({error:'Abra o caixa antes'}); const type=b.type==='withdrawal'?'withdrawal':'supply'; const m=await one(`INSERT INTO cash_movements(gym_id,register_id,type,direction,amount,method,description,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *`,[req.user!.gym_id,r.id,type,type==='withdrawal'?'out':'in',Number(b.amount),b.method||'cash',b.description||'',req.user!.id]); return reply.code(201).send(m);});
app.post('/api/cash/close',{preHandler:requireAuth},async(req:Req,reply)=>{const r=await one(`SELECT * FROM cash_registers WHERE gym_id=$1 AND status='open'`,[req.user!.gym_id]); if(!r)return reply.code(404).send({error:'Nenhum caixa aberto'}); const totals=await one(`SELECT COALESCE(sum(CASE WHEN direction='in' THEN amount ELSE -amount END),0) net FROM cash_movements WHERE register_id=$1`,[r.id]); const expected=money(Number(r.opening_amount)+Number(totals.net)); const actual=money(Number(body(req).closing_amount||0)); const closed=await one(`UPDATE cash_registers SET status='closed',closed_by=$1,closed_at=now(),closing_amount=$2,expected_amount=$3,difference=$4,notes=$5 WHERE id=$6 RETURNING *`,[req.user!.id,actual,expected,money(actual-expected),body(req).notes||null,r.id]); return {register:closed};});

app.post('/api/sales',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),items=Array.isArray(b.items)?b.items:[]; if(!items.length)return reply.code(400).send({error:'Venda sem itens'}); const client=await pool.connect(); try{await client.query('BEGIN'); let total=0; const normalized:any[]=[]; for(const it of items){let source=null; if(it.product_id)source=(await client.query(`SELECT * FROM products WHERE id=$1 AND gym_id=$2 AND active=true FOR UPDATE`,[it.product_id,req.user!.gym_id])).rows[0]; if(it.service_id)source=(await client.query(`SELECT * FROM services WHERE id=$1 AND gym_id=$2 AND active=true`,[it.service_id,req.user!.gym_id])).rows[0]; if(!source)throw new Error('Item inválido'); const qty=Number(it.quantity||1),price=Number(it.unit_price??source.price); if(it.product_id && Number(source.stock)<qty)throw new Error(`Estoque insuficiente: ${source.name}`); const line=money(qty*price); total+=line; normalized.push({it,source,qty,price,line}); } total=money(total-Number(b.discount||0)); const sale=(await client.query(`INSERT INTO sales(gym_id,student_id,total,discount,method,created_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING *`,[req.user!.gym_id,b.student_id||null,total,Number(b.discount||0),b.method||'pix',req.user!.id])).rows[0]; for(const n of normalized){await client.query(`INSERT INTO sale_items(sale_id,product_id,service_id,description,quantity,unit_price,total) VALUES($1,$2,$3,$4,$5,$6,$7)`,[sale.id,n.it.product_id||null,n.it.service_id||null,n.source.name,n.qty,n.price,n.line]); if(n.it.product_id)await client.query(`UPDATE products SET stock=stock-$1,updated_at=now() WHERE id=$2 AND gym_id=$3`,[n.qty,n.it.product_id,req.user!.gym_id]);} await client.query('COMMIT'); await addCashMovement(req.user!.gym_id,'sale',total,b.method||'pix','Venda',sale.id,req.user!.id); return reply.code(201).send(sale); }catch(e:any){await client.query('ROLLBACK');return reply.code(400).send({error:e.message||'Não foi possível concluir a venda'});}finally{client.release();}});
app.get('/api/sales',{preHandler:requireAuth},async(req:Req)=>q(`SELECT s.*,st.full_name student_name,(SELECT json_agg(si) FROM sale_items si WHERE si.sale_id=s.id) items FROM sales s LEFT JOIN students st ON st.id=s.student_id WHERE s.gym_id=$1 ORDER BY s.sold_at DESC LIMIT 300`,[req.user!.gym_id]));

