app.get('/api/reports/overview',{preHandler:requireAuth},async(req:Req)=>{const g=req.user!.gym_id; const [monthly,plans,methods,attendance]=await Promise.all([q(`SELECT to_char(date_trunc('month',created_at),'YYYY-MM') AS "month",COALESCE(sum(amount) FILTER(WHERE status='paid'),0) revenue,COALESCE(sum(amount) FILTER(WHERE status='pending'),0) pending FROM payments WHERE gym_id=$1 AND created_at>=now()-interval '12 months' GROUP BY 1 ORDER BY 1`,[g]),q(`SELECT p.name, count(e.id)::int enrollments,COALESCE(sum(e.amount),0) revenue FROM enrollments e JOIN plans p ON p.id=e.plan_id WHERE e.gym_id=$1 GROUP BY p.name ORDER BY revenue DESC`,[g]),q(`SELECT method,count(*)::int count,COALESCE(sum(amount),0) total FROM payments WHERE gym_id=$1 AND status='paid' GROUP BY method ORDER BY total DESC`,[g]),q(`SELECT to_char(date_trunc('day',checked_at),'YYYY-MM-DD') AS "day",count(*)::int checkins FROM checkins WHERE gym_id=$1 AND checked_at>=now()-interval '30 days' GROUP BY 1 ORDER BY 1`,[g])]); return {monthly,plans,methods,attendance};});

