app.put('/api/security/password',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req);if(!b.current_password||!b.new_password||String(b.new_password).length<8)return reply.code(400).send({error:'Informe a senha atual e uma nova senha com pelo menos 8 caracteres.'});const u=await one(`SELECT password_hash FROM users WHERE id=$1 AND gym_id=$2`,[req.user!.id,req.user!.gym_id]);if(!u||!(await argon2.verify(u.password_hash,b.current_password)))return reply.code(400).send({error:'Senha atual inválida.'});const hash=await argon2.hash(b.new_password);await q(`UPDATE users SET password_hash=$1,updated_at=now() WHERE id=$2 AND gym_id=$3`,[hash,req.user!.id,req.user!.gym_id]);return {ok:true};});

