// Portal do aluno
const studentAuth = async (req:any, reply:FastifyReply) => {
  const header = req.headers.authorization || '';
  if (!header.startsWith('Bearer ')) return reply.code(401).send({error:'Não autenticado'});
  const row = await one(`SELECT sa.student_id,sa.gym_id,s.full_name,s.email,s.phone,g.name gym_name FROM student_sessions ss JOIN student_accounts sa ON sa.id=ss.student_account_id JOIN students s ON s.id=sa.student_id JOIN gyms g ON g.id=sa.gym_id WHERE ss.token_hash=$1 AND ss.student_account_id=sa.id AND ss.gym_id=sa.gym_id AND sa.gym_id=s.gym_id AND s.gym_id=g.id AND ss.revoked_at IS NULL AND ss.expires_at>now() AND sa.status='active' AND s.status='active' AND g.active=true`, [hashToken(header.slice(7))]);
  if (!row) return reply.code(401).send({error:'Sessão expirada'}); req.student=row;
};
app.post('/student-auth/login',async(req,reply)=>{ const b=body(req); if(!b.gymSlug||!b.email||!b.password)return reply.code(400).send({error:'Informe academia, e-mail e senha'}); const account=await one(`SELECT sa.*,s.full_name,s.email student_email,s.phone,g.name gym_name FROM student_accounts sa JOIN students s ON s.id=sa.student_id JOIN gyms g ON g.id=sa.gym_id WHERE g.slug=$1 AND lower(sa.email)=lower($2) AND sa.status='active' AND s.status='active' AND g.active=true`,[b.gymSlug,b.email]); if(!account||!(await argon2.verify(account.password_hash,b.password)))return reply.code(401).send({error:'E-mail ou senha inválidos'}); const token=newToken(); await q(`INSERT INTO student_sessions(student_account_id,gym_id,token_hash,expires_at) VALUES($1,$2,$3,now()+interval '7 days')`,[account.id,account.gym_id,hashToken(token)]); await q(`UPDATE student_accounts SET last_login_at=now() WHERE id=$1`,[account.id]); return {token,student:{id:account.student_id,name:account.full_name,email:account.student_email||account.email,phone:account.phone,gymName:account.gym_name}}; });
app.post('/api/students/:id/portal-access',{preHandler:requireAuth},async(req:Req,reply)=>{ if(!['admin','manager','reception','instructor'].includes(req.user!.role))return reply.code(403).send({error:'Sem permissão'}); const b=body(req); if(!b.email||!b.password||String(b.password).length<8)return reply.code(400).send({error:'E-mail e senha de pelo menos 8 caracteres são obrigatórios'}); const student=await one(`SELECT id FROM students WHERE id=$1 AND gym_id=$2 AND status='active'`,[(req.params as any).id,req.user!.gym_id]); if(!student)return reply.code(404).send({error:'Aluno não encontrado'}); const h=await argon2.hash(b.password); await q(`INSERT INTO student_accounts(gym_id,student_id,email,password_hash) VALUES($1,$2,lower($3),$4) ON CONFLICT(student_id) DO UPDATE SET email=excluded.email,password_hash=excluded.password_hash,status='active',updated_at=now()`,[req.user!.gym_id,(req.params as any).id,b.email,h]); return reply.code(204).send(); });
app.get('/student-api/home',{preHandler:studentAuth},async(req:any)=>{ const g=req.student.gym_id,id=req.student.student_id; const [enrollment,workouts,appointments,payments]=await Promise.all([one(`SELECT e.starts_on,e.ends_on,e.status,p.name plan_name,p.price FROM enrollments e JOIN plans p ON p.id=e.plan_id WHERE e.student_id=$1 AND e.gym_id=$2 ORDER BY e.ends_on DESC LIMIT 1`,[id,g]),q(`SELECT w.id,w.name,w.objective,w.review_on,COALESCE(json_agg(json_build_object('id',x.id,'name',x.name,'muscle_group',x.muscle_group,'equipment',x.equipment,'instructions',x.instructions,'sets',we.sets,'reps',we.reps,'load',we.load,'rest',we.rest,'notes',we.notes) ORDER BY we.position) FILTER(WHERE x.id IS NOT NULL),'[]') exercises FROM workouts w LEFT JOIN workout_exercises we ON we.workout_id=w.id LEFT JOIN exercises x ON x.id=we.exercise_id WHERE w.student_id=$1 AND w.gym_id=$2 AND w.status='active' GROUP BY w.id ORDER BY w.updated_at DESC LIMIT 10`,[id,g]),q(`SELECT id,title,type,starts_at,ends_at,notes FROM appointments WHERE student_id=$1 AND gym_id=$2 AND starts_at>=now() ORDER BY starts_at LIMIT 20`,[id,g]),q(`SELECT amount,paid_at,method,status,due_at FROM payments WHERE student_id=$1 AND gym_id=$2 ORDER BY created_at DESC LIMIT 20`,[id,g])]); return {student:{id,name:req.student.full_name,email:req.student.email,phone:req.student.phone,gymName:req.student.gym_name},enrollment:enrollment||null,workouts,appointments,payments}; });
app.post('/student-api/logout',{preHandler:studentAuth},async(req:any)=>{const h=req.headers.authorization||'';await q(`UPDATE student_sessions SET revoked_at=now() WHERE token_hash=$1`,[hashToken(h.slice(7))]);return {ok:true};});

app.post('/student-api/checkins',{preHandler:studentAuth},async(req:any,reply)=>{const g=req.student.gym_id,id=req.student.student_id;const existing=await one(`SELECT * FROM checkins WHERE gym_id=$1 AND student_id=$2 AND checked_at>=CURRENT_DATE`,[g,id]);if(existing)return {already:true,checkin:existing};const enrollment=await one(`SELECT ends_on FROM enrollments WHERE gym_id=$1 AND student_id=$2 AND status<>'cancelled' ORDER BY ends_on DESC LIMIT 1`,[g,id]);if(enrollment?.ends_on&&new Date(enrollment.ends_on)<new Date())return reply.code(400).send({error:'Sua matrícula está vencida.'});const checkin=await one(`INSERT INTO checkins(gym_id,student_id,method) VALUES($1,$2,'student') RETURNING *`,[g,id]);return reply.code(201).send({already:false,checkin});});
app.get('/student-api/workout-history',{preHandler:studentAuth},async(req:any)=>q(`SELECT wc.id,wc.completed_at,w.name FROM workout_completions wc JOIN workouts w ON w.id=wc.workout_id WHERE wc.student_id=$1 AND wc.gym_id=$2 ORDER BY wc.completed_at DESC LIMIT 50`,[req.student.student_id,req.student.gym_id]));
app.post('/student-api/workouts/:id/complete',{preHandler:studentAuth},async(req:any,reply)=>{const id=(req.params as any).id;const own=await one(`SELECT id FROM workouts WHERE id=$1 AND student_id=$2 AND gym_id=$3 AND status='active'`,[id,req.student.student_id,req.student.gym_id]);if(!own)return reply.code(404).send({error:'Treino não encontrado'});return reply.code(201).send(await one(`INSERT INTO workout_completions(gym_id,student_id,workout_id) VALUES($1,$2,$3) RETURNING id,completed_at`,[req.student.gym_id,req.student.student_id,id]));});
app.get('/student-api/workouts/:id/logs',{preHandler:studentAuth},async(req:any)=>q(`SELECT id,workout_id,exercise_id,set_number,weight,reps,completed_at FROM workout_logs WHERE workout_id=$1 AND student_id=$2 ORDER BY completed_at DESC`,[(req.params as any).id,req.student.student_id]));
app.post('/student-api/workouts/:id/logs',{preHandler:studentAuth},async(req:any,reply)=>{const b=body(req),id=(req.params as any).id;if(!b.exercise_id||!Number.isInteger(Number(b.set_number))||Number(b.set_number)<1||Number(b.weight)<0||Number(b.reps)<1)return reply.code(400).send({error:'Informe exercício, série, carga e repetições válidos'});const own=await one(`SELECT id FROM workouts WHERE id=$1 AND student_id=$2 AND gym_id=$3 AND status='active'`,[id,req.student.student_id,req.student.gym_id]);if(!own)return reply.code(404).send({error:'Treino não encontrado'});return reply.code(201).send(await one(`INSERT INTO workout_logs(gym_id,student_id,workout_id,exercise_id,set_number,weight,reps) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *`,[req.student.gym_id,req.student.student_id,id,b.exercise_id,Number(b.set_number),Number(b.weight),Number(b.reps)]));});
