app.put('/student-api/nutrigym/goals',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),items=Array.isArray(b.goals)?b.goals:[b];if(!items.length||items.length>20)return reply.code(400).send({error:'Metas inválidas.'});const saved=[];for(const item of items){const type=nutritionText(item.goal_type ?? item.type,40,true),unit=nutritionText(item.unit,30,true),period=nutritionText(item.period,30,true),value=nutritionNumber(item.value,0,100000);if(type===undefined||unit===undefined||period===undefined||value===null||value===undefined)return reply.code(400).send({error:'Confira os dados das metas.'});saved.push(await one(`INSERT INTO nutrigym_goals(gym_id,student_id,goal_type,value,unit,period,active) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(gym_id,student_id,goal_type) DO UPDATE SET value=EXCLUDED.value,unit=EXCLUDED.unit,period=EXCLUDED.period,active=true,updated_at=now() RETURNING id,goal_type,value,unit,period,active,created_at,updated_at`,[s.gym,s.student,type,value,unit,period,item.active!==false]));}return saved;});

