app.get('/student-api/nutrigym/assistant/messages',{preHandler:studentAuth},async(req:any)=>{const s=nutritionScope(req);return q(`SELECT id,role,content,has_image,created_at FROM nutrigym_chat_messages WHERE gym_id=$1 AND student_id=$2 ORDER BY created_at DESC LIMIT 50`,[s.gym,s.student]).then(rows=>rows.reverse());});
app.post('/student-api/nutrigym/assistant',{preHandler:studentAuth},async(req:any,reply)=>{
  const b=body(req), message=nutritionText(b.message||'Analise esta refeição.',500,true), imageDataUrl=typeof b.image_data_url==='string'?b.image_data_url:undefined;
  if(message===undefined || (imageDataUrl && (!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(imageDataUrl) || imageDataUrl.length>8_000_000))) return reply.code(400).send({error:'Mensagem ou imagem inválida.'});
  const s=nutritionScope(req),context=await nutritionContext(s.gym,s.student);
  if(!context.profile) return {text:'Complete seu perfil nutricional para receber orientações gerais. Este assistente não substitui um nutricionista.'};
  const restrictions=context.profile.allergies||context.profile.restrictions,latest=context.meals[0],hint=latest?` Seu último registro foi ${latest.meal_type.toLowerCase()}.`:'';
  let ai:string|null=null;let action:any=null;const lower=message.toLowerCase().trim();
  const waterMatch=lower.match(/^(?:bebi|tomei|adicionei|registrei)\\s+(?:água\\s+)?(\\d+(?:[.,]\\d+)?)\\s*(ml|mililitros|l|litros)\\b/);
  if(!imageDataUrl&&waterMatch){let amount=Number(waterMatch[1].replace(',','.'));if(['l','litros'].includes(waterMatch[2]))amount*=1000;if(amount>=1&&amount<=10000){await q(`INSERT INTO nutrigym_hydration(gym_id,student_id,hydration_date,amount_ml,hydration_time) VALUES($1,$2,CURRENT_DATE,$3,LOCALTIME)`,[s.gym,s.student,Math.round(amount)]);action={type:'hydration',amount_ml:Math.round(amount)};}}
  const mealMatch=!imageDataUrl&&/^(comi|almocei|jantei|lanchei|tomei café|tomei cafe|fiz uma refeição|fiz uma refeicao)\\b/.test(lower);
  if(mealMatch){const type=lower.includes('café')||lower.includes('cafe')?'Café da manhã':lower.includes('almo')?'Almoço':lower.includes('jant')?'Jantar':lower.includes('lanche')?'Lanche':'Refeição';await q(`INSERT INTO nutrigym_meals(gym_id,student_id,meal_date,meal_time,meal_type,description,calories,protein_g,carbs_g,fat_g,notes) VALUES($1,$2,CURRENT_DATE,LOCALTIME,$3,$4,0,0,0,0,$5)`,[s.gym,s.student,type,message,'Registrada pelo chat; valores nutricionais não informados']);action={type:'meal',meal_type:type};}
  if(!action&&!imageDataUrl)ai=await askGroqNutrition(message,context);const fallback=imageDataUrl?'Não consegui concluir a análise da foto agora. Você pode descrever os alimentos por texto para eu organizar o registro.':action?.type==='hydration'?`Registrei ${action.amount_ml} ml de água. Sua hidratação já foi atualizada.`:action?.type==='meal'?`Registrei seu ${String(action.meal_type).toLowerCase()}. Se quiser, informe as quantidades para completar os dados.`:`Considerando seu objetivo de ${String(context.profile.objective).toLowerCase()}${hint}${restrictions?' Já vou considerar suas restrições.':''} Posso ajudar a organizar seus registros e encontrar opções práticas para sua rotina.`;
  const text=ai||fallback; await q(`INSERT INTO nutrigym_chat_messages(gym_id,student_id,role,content,has_image) VALUES($1,$2,'user',$3,$4),($1,$2,'assistant',$5,false)`,[s.gym,s.student,message,Boolean(imageDataUrl),text]);
  return {text,provider:ai?'groq':action?'rules':'fallback',action,context:{objective:context.profile.objective,has_restrictions:Boolean(restrictions),recent_meals:context.meals.length,active_goals:context.goals.length,has_plan:Boolean(context.plan),image_requested:Boolean(imageDataUrl)}};
});


const nutritionContext=async(gym:string,student:string)=>{
  const [studentData,profile,meals,goals,checkin,checkinHistory,workouts,workoutHistory,assessments,hydration,memories,plan]=await Promise.all([
    one(`SELECT full_name,birth_date,gender,primary_goal,weekly_frequency,session_duration,training_level,training_experience_months,limitations,preferences FROM students WHERE gym_id=$1 AND id=$2`,[gym,student]),
    one(`SELECT objective,weight_kg,height_cm,age,sex,activity_level,preferences,restrictions,allergies,dislikes,wake_time,sleep_time,training_time,meals_per_day,budget_level,cooking_time FROM nutrigym_profiles WHERE gym_id=$1 AND student_id=$2`,[gym,student]),
    q(`SELECT meal_date,meal_type,description,meal_time,calories,protein_g,carbs_g,fat_g FROM nutrigym_meals WHERE gym_id=$1 AND student_id=$2 ORDER BY meal_date DESC,created_at DESC LIMIT 14`,[gym,student]),
    q(`SELECT goal_type,value,unit,period FROM nutrigym_goals WHERE gym_id=$1 AND student_id=$2 AND active=true`,[gym,student]),
    one(`SELECT mood,hunger,energy,night_hunger,sleep_quality,checkin_date FROM nutrigym_daily_checkins WHERE gym_id=$1 AND student_id=$2 ORDER BY checkin_date DESC LIMIT 1`,[gym,student]),
    q(`SELECT checkin_date,weight_kg,measurements,notes FROM nutrigym_checkins WHERE gym_id=$1 AND student_id=$2 ORDER BY checkin_date DESC LIMIT 12`,[gym,student]),
    q(`SELECT w.name,w.objective,w.review_on,w.starts_on FROM workouts w WHERE w.gym_id=$1 AND w.student_id=$2 AND w.status='active' ORDER BY w.updated_at DESC LIMIT 5`,[gym,student]),
    q(`SELECT wc.completed_at,w.name,w.objective FROM workout_completions wc JOIN workouts w ON w.id=wc.workout_id WHERE wc.gym_id=$1 AND wc.student_id=$2 ORDER BY wc.completed_at DESC LIMIT 12`,[gym,student]),
    q(`SELECT measured_at,weight,height,body_fat,muscle_mass,waist,chest,arm,thigh,notes FROM assessments WHERE gym_id=$1 AND student_id=$2 ORDER BY measured_at DESC LIMIT 12`,[gym,student]),
    q(`SELECT hydration_date,COALESCE(sum(amount_ml),0)::int amount_ml FROM nutrigym_hydration WHERE gym_id=$1 AND student_id=$2 AND hydration_date>=CURRENT_DATE-interval '30 days' GROUP BY hydration_date ORDER BY hydration_date DESC`,[gym,student]),
    q(`SELECT memory_key,memory_value FROM nutrigym_memories WHERE gym_id=$1 AND student_id=$2 AND active=true ORDER BY updated_at DESC LIMIT 20`,[gym,student]),
    one(`SELECT version,title,professional_name,status,content FROM nutrigym_plan_versions WHERE gym_id=$1 AND student_id=$2 AND status='active' ORDER BY version DESC LIMIT 1`,[gym,student])
  ]);
  return {student:studentData,profile,meals,goals,checkin,checkinHistory,workouts,workoutHistory,assessments,hydration,memories,plan};
};
app.get('/student-api/nutrigym/plan',{preHandler:studentAuth},async(req:any)=>{const s=nutritionScope(req);return one(`SELECT id,version,title,status,professional_name,content,created_at,approved_at FROM nutrigym_plan_versions WHERE gym_id=$1 AND student_id=$2 AND status='active' ORDER BY version DESC LIMIT 1`,[s.gym,s.student]);});
app.get('/student-api/nutrigym/daily-checkins',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),raw=(req.query as any)?.date,day=raw?nutritionDate(raw):await studentToday();if(day===undefined)return reply.code(400).send({error:'Data inválida'});return one(`SELECT id,checkin_date,mood,hunger,energy,night_hunger,sleep_quality,notes,created_at,updated_at FROM nutrigym_daily_checkins WHERE gym_id=$1 AND student_id=$2 AND checkin_date=$3`,[s.gym,s.student,day]);});
app.put('/student-api/nutrigym/daily-checkins',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),raw=nutritionDate(b.checkin_date??b.date),day=raw===null?await studentToday():raw,mood=nutritionText(b.mood,20),hunger=nutritionNumber(b.hunger,0,10,true),energy=nutritionNumber(b.energy,0,10,true),night=nutritionNumber(b.night_hunger,0,10,true),sleep=nutritionNumber(b.sleep_quality??b.sleep,0,10,true),notes=nutritionText(b.notes,500);if(day===undefined||[hunger,energy,night,sleep].some(x=>x===undefined)||!['very_good','good','normal','tired','poor_sleep','unwell',null].includes(mood))return reply.code(400).send({error:'Confira o check-in de hábitos.'});return one(`INSERT INTO nutrigym_daily_checkins(gym_id,student_id,checkin_date,mood,hunger,energy,night_hunger,sleep_quality,notes) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(gym_id,student_id,checkin_date) DO UPDATE SET mood=EXCLUDED.mood,hunger=EXCLUDED.hunger,energy=EXCLUDED.energy,night_hunger=EXCLUDED.night_hunger,sleep_quality=EXCLUDED.sleep_quality,notes=EXCLUDED.notes,updated_at=now() RETURNING *`,[s.gym,s.student,day,mood,hunger,energy,night,sleep,notes]);});
app.get('/student-api/nutrigym/memories',{preHandler:studentAuth},async(req:any)=>{const s=nutritionScope(req);return q(`SELECT id,memory_key,memory_value,created_at,updated_at FROM nutrigym_memories WHERE gym_id=$1 AND student_id=$2 AND active=true ORDER BY updated_at DESC`,[s.gym,s.student]);});
app.post('/student-api/nutrigym/memories',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),key=nutritionText(b.memory_key??b.key,80,true),value=nutritionText(b.memory_value??b.value,500,true);if(key===undefined||value===undefined)return reply.code(400).send({error:'Informe a memória.'});return reply.code(201).send(await one(`INSERT INTO nutrigym_memories(gym_id,student_id,memory_key,memory_value) VALUES($1,$2,$3,$4) RETURNING id,memory_key,memory_value,created_at,updated_at`,[s.gym,s.student,key,value]));});
app.put('/student-api/nutrigym/memories/:id',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),key=nutritionText(b.memory_key??b.key,80,true),value=nutritionText(b.memory_value??b.value,500,true);if(key===undefined||value===undefined)return reply.code(400).send({error:'Informe a memória.'});const row=await one(`UPDATE nutrigym_memories SET memory_key=$1,memory_value=$2,updated_at=now() WHERE id=$3 AND gym_id=$4 AND student_id=$5 AND active=true RETURNING id,memory_key,memory_value,created_at,updated_at`,[key,value,(req.params as any).id,s.gym,s.student]);return row||reply.code(404).send({error:'Memória não encontrada'});});
app.delete('/student-api/nutrigym/memories/:id',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),row=await one(`UPDATE nutrigym_memories SET active=false,updated_at=now() WHERE id=$1 AND gym_id=$2 AND student_id=$3 RETURNING id`,[(req.params as any).id,s.gym,s.student]);return row?{ok:true}:reply.code(404).send({error:'Memória não encontrada'});});
app.get('/student-api/nutrigym/shopping',{preHandler:studentAuth},async(req:any)=>{const s=nutritionScope(req);return q(`SELECT id,category,item,quantity,purchased,created_at,updated_at FROM nutrigym_shopping_items WHERE gym_id=$1 AND student_id=$2 ORDER BY purchased,category,item`,[s.gym,s.student]);});
app.post('/student-api/nutrigym/shopping',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),category=nutritionText(b.category,40)||'Outros',item=nutritionText(b.item,160,true),quantity=nutritionText(b.quantity,60);if(item===undefined)return reply.code(400).send({error:'Informe o item.'});return reply.code(201).send(await one(`INSERT INTO nutrigym_shopping_items(gym_id,student_id,category,item,quantity) VALUES($1,$2,$3,$4,$5) RETURNING *`,[s.gym,s.student,category,item,quantity]));});
app.put('/student-api/nutrigym/shopping/:id',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),purchased=b.purchased===undefined?false:Boolean(b.purchased),item=nutritionText(b.item,160,true),quantity=nutritionText(b.quantity,60);if(item===undefined)return reply.code(400).send({error:'Informe o item.'});const row=await one(`UPDATE nutrigym_shopping_items SET item=$1,quantity=$2,purchased=$3,updated_at=now() WHERE id=$4 AND gym_id=$5 AND student_id=$6 RETURNING *`,[item,quantity,purchased,(req.params as any).id,s.gym,s.student]);return row||reply.code(404).send({error:'Item não encontrado'});});
app.delete('/student-api/nutrigym/shopping/:id',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),row=await one(`DELETE FROM nutrigym_shopping_items WHERE id=$1 AND gym_id=$2 AND student_id=$3 RETURNING id`,[(req.params as any).id,s.gym,s.student]);return row?{ok:true}:reply.code(404).send({error:'Item não encontrado'});});

async function init(){ const schema=await fs.readFile(path.join(process.cwd(),'schema/001_schema.sql'),'utf8'); await pool.query(schema); await pool.query(`ALTER TABLE plans ADD COLUMN IF NOT EXISTS price numeric(12,2) NOT NULL DEFAULT 0; ALTER TABLE plans ADD COLUMN IF NOT EXISTS duration_days int NOT NULL DEFAULT 30; ALTER TABLE plans ADD COLUMN IF NOT EXISTS description text; ALTER TABLE plans ADD COLUMN IF NOT EXISTS status varchar(20) NOT NULL DEFAULT 'active'; ALTER TABLE plans ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now(); CREATE TABLE IF NOT EXISTS student_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gym_id uuid NOT NULL REFERENCES gyms(id) ON DELETE CASCADE, student_id uuid NOT NULL UNIQUE REFERENCES students(id) ON DELETE CASCADE, email varchar(254) NOT NULL, password_hash text NOT NULL, status varchar(20) NOT NULL DEFAULT 'active', last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(gym_id,email)); CREATE TABLE IF NOT EXISTS student_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_account_id uuid NOT NULL REFERENCES student_accounts(id) ON DELETE CASCADE, gym_id uuid NOT NULL REFERENCES gyms(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS student_sessions_lookup_idx ON student_sessions(token_hash) WHERE revoked_at IS NULL; CREATE TABLE IF NOT EXISTS workout_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gym_id uuid NOT NULL REFERENCES gyms(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, workout_id uuid NOT NULL REFERENCES workouts(id) ON DELETE CASCADE, exercise_id uuid NOT NULL REFERENCES exercises(id), set_number int NOT NULL CHECK(set_number>0), weight numeric(10,2) NOT NULL CHECK(weight>=0), reps int NOT NULL CHECK(reps>0), completed_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS workout_logs_student_idx ON workout_logs(student_id,completed_at DESC); CREATE TABLE IF NOT EXISTS workout_completions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gym_id uuid NOT NULL REFERENCES gyms(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, workout_id uuid NOT NULL REFERENCES workouts(id), completed_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS workout_completions_student_idx ON workout_completions(student_id,completed_at DESC);`); const nutrition=await fs.readFile(path.join(process.cwd(),'schema/002_nutrigym.sql'),'utf8'); await pool.query(nutrition); const nutritionPlus=await fs.readFile(path.join(process.cwd(),'schema/003_nutrigym_plus.sql'),'utf8'); await pool.query(nutritionPlus); const nutritionChat=await fs.readFile(path.join(process.cwd(),'schema/004_nutrigym_chat.sql'),'utf8'); await pool.query(nutritionChat); }

